class Reflog:
    def __init__(self):
        self.entries = []
        self.head = None

    def move(self, sha, action):
        self.entries.insert(0, (sha, action))
        self.head = sha

    def show(self):
        return [f"{sha} HEAD@{{{i}}}: {action}" for i, (sha, action) in enumerate(self.entries)]

    def recover(self, index):
        sha, _ = self.entries[index]
        self.move(sha, f"reset: moving to {sha}")
        return sha


HOOKS = {
    "pre-commit": ["ejecutar linter", "ejecutar tests rápidos"],
    "post-commit": ["notificar al canal de equipo"],
}


def run_hook(name):
    steps = HOOKS.get(name, [])
    return [f"{name}: {step}" for step in steps]


log = Reflog()
log.move("4a5b6c7", "checkout: moving from develop to master")
log.move("9k0l1m2", "commit: Fix critical bug")
log.move("5x6y7z8", "reset: moving to 5x6y7z8")

for line in log.show():
    print(line)

recovered = log.recover(2)
print(f"recuperado: {recovered}")

for line in run_hook("pre-commit"):
    print(line)
